def compile_mjcf(facts,out):
 c={'base':None,'front_upright':None,'rear_upright':None,'front_bearing':None,'rear_bearing':None,'wind_rotor':'crank_rotation','crankshaft':'crank_rotation','connecting_rod':'big_end_hinge','piston_slider':'crosshead_slide','wrist_pin':'crosshead_slide','guide_frame':None,'pump_barrel':None,'pump_rod':'crosshead_slide','pump_piston':'crosshead_slide'}
 x=[('wind_rotor','crankshaft','exclude','Interference press fit rigidly carried.',['relation/rotor_press_fit'],['fit/crankshaft/rotor_seat/wind_rotor/hub_bore','pair/crankshaft/wind_rotor','nearby/crankshaft/wind_rotor']),('crankshaft','front_bearing','exclude','Clearance journal represented by hinge.',['relation/front_shaft_journal'],['fit/front_bearing/journal_bore/crankshaft/front_journal','pair/crankshaft/front_bearing','nearby/crankshaft/front_bearing']),('crankshaft','rear_bearing','exclude','Clearance journal represented by hinge.',['relation/rear_shaft_journal'],['fit/rear_bearing/journal_bore/crankshaft/rear_journal','pair/crankshaft/rear_bearing','nearby/crankshaft/rear_bearing']),('crankshaft','connecting_rod','keep','Shared crankshaft web remains collidable; local pin center is hinged.',['relation/crank_big_end_revolute'],['fit/crankshaft/eccentric_pin/connecting_rod/big_end_bore','pair/connecting_rod/crankshaft','nearby/connecting_rod/crankshaft']),('wrist_pin','connecting_rod','exclude','Dedicated pin bearing represented by closure.',['relation/rod_small_end_revolute'],['fit/wrist_pin/pin_shaft/connecting_rod/small_end_bore','pair/connecting_rod/wrist_pin','nearby/connecting_rod/wrist_pin']),('piston_slider','wrist_pin','exclude','Interference press fit rigidly carried.',['relation/wrist_pin_into_slider'],['fit/piston_slider/wrist_pin_seat/wrist_pin/pin_shaft','pair/piston_slider/wrist_pin','nearby/piston_slider/wrist_pin']),('piston_slider','pump_rod','exclude','Interference press fit rigidly carried.',['relation/pump_rod_into_slider'],['fit/piston_slider/pump_rod_seat/pump_rod/upper_press_seat','pair/piston_slider/pump_rod','nearby/piston_slider/pump_rod']),('pump_rod','pump_piston','exclude','Interference press fit rigidly carried.',['relation/pump_piston_on_rod'],['fit/pump_rod/piston_seat/pump_piston/rod_bore','pair/pump_piston/pump_rod','nearby/pump_piston/pump_rod'])]
 n=[('wind_rotor','front_upright','front_upright/wind_rotor'),('wind_rotor','front_bearing','front_bearing/wind_rotor'),('wind_rotor','base','base/wind_rotor'),('wind_rotor','rear_upright','rear_upright/wind_rotor'),('wind_rotor','rear_bearing','rear_bearing/wind_rotor'),('crankshaft','front_upright','crankshaft/front_upright'),('crankshaft','rear_upright','crankshaft/rear_upright'),('crankshaft','guide_frame','crankshaft/guide_frame'),('crankshaft','piston_slider','crankshaft/piston_slider'),('crankshaft','wrist_pin','crankshaft/wrist_pin'),('crankshaft','pump_rod','crankshaft/pump_rod'),('crankshaft','pump_barrel','crankshaft/pump_barrel'),('connecting_rod','piston_slider','connecting_rod/piston_slider'),('connecting_rod','guide_frame','connecting_rod/guide_frame'),('connecting_rod','pump_rod','connecting_rod/pump_rod'),('connecting_rod','pump_barrel','connecting_rod/pump_barrel'),('connecting_rod','rear_upright','connecting_rod/rear_upright'),('connecting_rod','rear_bearing','connecting_rod/rear_bearing'),('connecting_rod','pump_piston','connecting_rod/pump_piston'),('connecting_rod','base','base/connecting_rod'),('piston_slider','guide_frame','guide_frame/piston_slider'),('piston_slider','pump_barrel','piston_slider/pump_barrel'),('piston_slider','rear_upright','piston_slider/rear_upright'),('piston_slider','pump_piston','piston_slider/pump_piston'),('wrist_pin','guide_frame','guide_frame/wrist_pin'),('wrist_pin','pump_rod','pump_rod/wrist_pin'),('pump_rod','guide_frame','guide_frame/pump_rod'),('pump_rod','pump_barrel','pump_barrel/pump_rod'),('pump_rod','base','base/pump_rod'),('pump_piston','guide_frame','guide_frame/pump_piston'),('pump_piston','pump_barrel','pump_barrel/pump_piston'),('pump_piston','base','base/pump_piston')]
 for a,b,k in n:x.append((a,b,'exclude','Separated real meshes have no contact function; exact proxy risk excluded.',['link/'+a,'link/'+b],['pair/'+k,'nearby/'+k]))
 q=[]
 for a,b,z,r,s,f in x:q.append({'pair':[a,b],'action':z,'reason':r,'source_entity_ids':s,'fact_ids':f})
 e=[['base','front_upright'],['front_upright','front_bearing'],['base','rear_upright'],['rear_upright','rear_bearing'],['base','guide_frame'],['base','pump_barrel'],['base','crankshaft'],['crankshaft','wind_rotor'],['crankshaft','connecting_rod'],['base','piston_slider'],['piston_slider','wrist_pin'],['piston_slider','pump_rod'],['pump_rod','pump_piston']]
 out.topology_plan({'coordinate_map':c,'tree_edges':e,'closure_edges':[['connecting_rod','wrist_pin','small_end_connect']],'rigid_carried':[['crankshaft','wind_rotor'],['piston_slider','wrist_pin'],['piston_slider','pump_rod'],['pump_rod','pump_piston']],'independent_coaxial':[],'transmissions':[{'name':'rotor_to_crankshaft_press_drive','ratio':1.0,'representation':'same_coordinate'}],'contact_decisions':q,'support_ground':True,'support_strategy':'Fixed base uses ground; below-grade pump rod alone is ground-excluded.'})
 for a,p in [('base',''),('front_upright','base'),('front_bearing','front_upright'),('rear_upright','base'),('rear_bearing','rear_upright'),('guide_frame','base'),('pump_barrel','base'),('crankshaft','base')]:out.body(a,p)
 out.joint('crankshaft','crank_rotation','hinge',(0,1,0),(0,0,110),'world');out.body('wind_rotor','crankshaft');out.body('connecting_rod','crankshaft');out.joint('connecting_rod','big_end_hinge','hinge',(0,1,0),(18,45,110),'world');out.body('piston_slider','base');out.joint('piston_slider','crosshead_slide','slide',(0,0,1),(0,45,40.2862997682665),'world');out.body('wrist_pin','piston_slider');out.body('pump_rod','piston_slider');out.body('pump_piston','pump_rod')
 out.connect('small_end_connect','connecting_rod','wrist_pin',(0,0.045,0.0402862997682665),'Wrist-pin closure.',['relation/rod_small_end_revolute'],['fit/wrist_pin/pin_shaft/connecting_rod/small_end_bore'])
 for a,b,z,r,s,f in x:
  if z=='exclude':out.exclude(a,b,r,s,f)
 out.exclude_ground('pump_rod','Runtime evidence shows intended below-grade travel is stalled by ground.',['link/pump_rod','motion_joint/vertical_crosshead_guide'],['pair/base/pump_rod','nearby/base/pump_rod'])
 for eid in facts['entity_ids']:
  g='base'
  if eid[:5]=='link/':g=eid[5:]
  if eid=='motion_joint/supported_crankshaft_rotation':g='crank_rotation'
  if eid=='motion_joint/vertical_crosshead_guide':g='crosshead_slide'
  out.decision(eid,'represented_by',[g],'Represented by emitted topology and contact classification.',[eid])
